SELECT r.id,r.user_id,r.node_id,COALESCE(r.ingress_group_id,0) AS ingress_group_id,COALESCE(ig.name,'') AS ingress_group_name,COALESCE(ig.connection_address,'') AS ingress_connection_address,COALESCE((SELECT jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'public_address',x.public_address,'enabled',x.enabled,'online',COALESCE(x.enabled AND x.last_seen>now()-interval '12 seconds',false),'status',CASE WHEN NOT x.enabled THEN 'disabled' WHEN r.ingress_group_id IS NOT NULL AND (NOT COALESCE(ig.enabled,false) OR NOT EXISTS(SELECT 1 FROM user_node_groups zug WHERE zug.user_id=r.user_id AND zug.group_id=r.ingress_group_id)) THEN 'unauthorized' WHEN NOT EXISTS(SELECT 1 FROM user_nodes un WHERE un.user_id=r.user_id AND un.node_id=x.id) THEN 'unauthorized' WHEN r.egress_node_id IS NULL AND r.egress_group_id IS NULL AND NOT x.allow_direct THEN 'unauthorized' WHEN (r.egress_node_id IS NOT NULL OR r.egress_group_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM rule_outbound_routes zo WHERE zo.rule_id=r.id AND zo.ingress_node_id=x.id) THEN 'unauthorized' WHEN r.ingress_group_id IS NOT NULL AND r.egress_node_id IS NOT NULL AND COALESCE((SELECT protocol_version FROM nodes WHERE id=r.egress_node_id),0)<$6 THEN 'upgrade_required' WHEN r.ingress_group_id IS NOT NULL AND r.egress_group_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM rule_outbound_routes zo JOIN nodes zx ON zx.id=zo.egress_node_id WHERE zo.rule_id=r.id AND zo.ingress_node_id=x.id AND zx.protocol_version >= $6) THEN 'upgrade_required' WHEN x.last_seen IS NULL OR x.last_seen<now()-interval '12 seconds' THEN 'offline' WHEN x.sync_error<>'' THEN 'failed' WHEN x.applied_revision<r.config_revision THEN 'pending' ELSE 'active' END,'sync_error',x.sync_error,'applied_revision',x.applied_revision,'config_revision',r.config_revision) ORDER BY x.id) FROM rule_ingress_nodes ri JOIN nodes x ON x.id=ri.node_id WHERE ri.rule_id=r.id),'[]') AS ingress_nodes,COALESCE(r.egress_node_id,0) AS egress_node_id,COALESCE(r.egress_group_id,0) AS egress_group_id,COALESCE(eg.name,'') AS egress_group_name,COALESCE(en.name,'') AS egress_node_name,COALESCE(en.tunnel_protocol,'') AS egress_tunnel_protocol,r.protocol,r.listen_host,COALESCE(ti.port,r.listen_port) AS listen_port,COALESCE(r.tls_inbound_id,0) AS tls_inbound_id,r.sni_names,r.tls_alpn,r.origin_tls,r.target_host,r.target_port,r.enabled,r.name,r.group_id,r.targets,r.balance,r.proxy_accept,r.proxy_send,r.proxy_trusted_cidrs,r.traffic_baseline,r.config_revision,u.rule_speed_bps/125000 AS speed_mbps,u.rule_ip_limit AS ip_limit,u.rule_connection_limit AS connection_limit,u.username,n.name AS node_name,n.public_address,n.last_seen,n.sync_error,n.applied_revision,
 COALESCE(g.name,'') AS group_name,GREATEST(COALESCE((SELECT sum(t.traffic) FROM all_rule_usage t WHERE t.rule_id=r.id),0)::bigint-r.traffic_baseline,0) AS traffic_bytes,
 CASE WHEN NOT r.enabled THEN 'disabled' WHEN NOT u.account_enabled THEN 'user_disabled' WHEN u.plan_id IS NULL THEN 'no_plan' WHEN NOT u.plan_enabled THEN 'plan_disabled' WHEN u.expires_at<=now() THEN 'expired' WHEN r.ingress_group_id IS NOT NULL AND (NOT COALESCE(ig.enabled,false) OR NOT EXISTS(SELECT 1 FROM user_node_groups ug WHERE ug.user_id=r.user_id AND ug.group_id=r.ingress_group_id)) THEN 'unauthorized' WHEN r.ingress_group_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM rule_ingress_nodes ri JOIN nodes x ON x.id=ri.node_id AND x.enabled WHERE ri.rule_id=r.id) THEN 'offline' WHEN NOT n.ingress_enabled OR NOT EXISTS(SELECT 1 FROM user_nodes un WHERE un.user_id=r.user_id AND un.node_id=n.id) OR (r.egress_node_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM user_nodes un WHERE un.user_id=r.user_id AND un.node_id=r.egress_node_id)) THEN 'unauthorized'
 WHEN r.egress_group_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM rule_outbound_routes o WHERE o.rule_id=r.id AND o.ingress_node_id=n.id) THEN 'unauthorized'
 WHEN r.ingress_group_id IS NOT NULL AND r.egress_node_id IS NOT NULL AND en.protocol_version<$6 THEN 'upgrade_required'
 WHEN r.egress_group_id IS NOT NULL AND n.protocol_version<24 THEN 'upgrade_required'
 WHEN r.egress_group_id IS NOT NULL AND gc.compatible=0 THEN 'upgrade_required'
 WHEN r.egress_group_id IS NOT NULL AND gc.usable=0 AND gc.online_compatible>0 THEN 'bandwidth_required'
 WHEN n.protocol_version<25 AND r.egress_group_id IS NULL AND n.ingress_rate+COALESCE(en.egress_rate,0)<>10000 THEN 'upgrade_required'
 WHEN u.quota_bytes>=0 AND (r.egress_group_id IS NULL AND n.ingress_rate+COALESCE(en.egress_rate,0)>0 OR r.egress_group_id IS NOT NULL AND gc.free_usable=0) AND (u.quota_bytes<=u.traffic_base_bytes+COALESCE((SELECT sum(charged_bytes) FROM current_grants WHERE user_id=u.id),0) OR u.quota_bytes<u.traffic_base_bytes+COALESCE((SELECT sum(issued-released+unlimited_spent) FROM current_grants WHERE user_id=u.id),0)) THEN 'quota_exhausted'
 WHEN r.egress_group_id IS NOT NULL AND gc.online_usable=0 THEN 'offline'
	 WHEN n.last_seen IS NULL OR n.last_seen<now()-interval '12 seconds' OR (en.id IS NOT NULL AND (en.last_seen IS NULL OR en.last_seen<now()-interval '12 seconds')) THEN 'offline'
	 WHEN $3 AND (n.protocol_version<14 OR (en.id IS NOT NULL AND en.protocol_version<14)) THEN 'upgrade_required'
 WHEN (r.tls_inbound_id IS NOT NULL AND n.protocol_version<21) OR (r.origin_tls->>'enabled'='true' AND n.protocol_version<20) THEN 'upgrade_required'
 WHEN r.tls_inbound_id IS NULL AND n.tls_inbound_only AND r.protocol='tcp' THEN 'tls_required'
 WHEN r.tls_inbound_id IS NOT NULL AND ti.config->>'enabled'<>'true' THEN 'inbound_disabled'
 WHEN (r.proxy_accept<>'off' OR ti.config->>'proxy_accept'='auto') AND $4 THEN 'proxy_untrusted'
 WHEN en.tunnel_protocol='tls_tcp' AND en.tls_config->>'padding_enabled'='true' AND (n.protocol_version<23 OR en.protocol_version<23) THEN 'upgrade_required'
 WHEN (en.tunnel_protocol IN ('random_tcp','random_h2','random_udp','dtls_udp') OR en.tunnel_protocol='tls_tcp' AND en.tls_config->>'padding_enabled'='true' AND en.mux_config->>'enabled'='true') AND (n.protocol_version<$5 OR en.protocol_version<$5) THEN 'upgrade_required'
 WHEN en.mux_config->>'enabled'='true' AND en.tunnel_protocol IN ('plain_tcp','tls_tcp','random_tcp','plain_udp','dtls_udp','random_udp') AND (n.protocol_version<34 OR en.protocol_version<34) THEN 'upgrade_required'
 WHEN en.brutal_enabled AND en.tunnel_protocol IN ('tls_h3','plain_udp','dtls_udp','random_udp') AND (n.protocol_version<32 OR en.protocol_version<32) THEN 'upgrade_required'
 WHEN en.brutal_enabled AND en.tunnel_protocol IN ('tls_h3','plain_udp','dtls_udp','random_udp') AND (n.bandwidth_up_mbps=0 OR n.bandwidth_down_mbps=0 OR en.bandwidth_up_mbps=0 OR en.bandwidth_down_mbps=0) THEN 'bandwidth_required'
 WHEN en.tunnel_protocol='tls_h3' AND en.tls_config->'quic_padding'->>'enabled'='true' AND (n.protocol_version<29 OR en.protocol_version<29) THEN 'upgrade_required'
 WHEN en.tunnel_protocol='tls_h3' AND (n.protocol_version<28 OR en.protocol_version<28) THEN 'upgrade_required'
 WHEN en.tunnel_protocol='random_udp' AND (n.protocol_version<27 OR en.protocol_version<27) THEN 'upgrade_required'
 WHEN en.tunnel_protocol IN ('random_tcp','random_h2') AND (n.protocol_version<26 OR en.protocol_version<26) THEN 'upgrade_required'
 WHEN en.tunnel_protocol IN ('plain_udp','dtls_udp','random_udp') AND (n.protocol_version<17 OR en.protocol_version<17) THEN 'upgrade_required'
 WHEN r.protocol<>'tcp' AND (n.protocol_version<16 OR (en.id IS NOT NULL AND en.protocol_version<16)) THEN 'upgrade_required'
 WHEN r.proxy_accept='auto' AND n.protocol_version<10 THEN 'upgrade_required'
	 WHEN en.tunnel_protocol='tls_h2' AND (n.protocol_version<11 OR en.protocol_version<11) THEN 'upgrade_required'
 WHEN en.tunnel_protocol IN ('tls_tcp','plain_h2') AND (n.protocol_version<13 OR en.protocol_version<13) THEN 'upgrade_required'
	 WHEN n.sync_error<>'' OR COALESCE(en.sync_error,'')<>'' THEN 'failed' WHEN n.applied_revision<r.config_revision OR (en.id IS NOT NULL AND en.applied_revision<r.config_revision) THEN 'pending' ELSE 'active' END AS status
	 FROM rules r JOIN user_entitlements u ON u.id=r.user_id JOIN nodes n ON n.id=COALESCE((SELECT ri.node_id FROM rule_ingress_nodes ri JOIN nodes x ON x.id=ri.node_id WHERE ri.rule_id=r.id ORDER BY x.enabled DESC,ri.node_id LIMIT 1),r.node_id) LEFT JOIN node_groups ig ON ig.id=r.ingress_group_id LEFT JOIN nodes en ON en.id=r.egress_node_id LEFT JOIN node_groups eg ON eg.id=r.egress_group_id LEFT JOIN node_tls_inbounds ti ON ti.id=r.tls_inbound_id LEFT JOIN rule_groups g ON g.id=r.group_id
 LEFT JOIN LATERAL (
  SELECT count(*) FILTER(WHERE c.compatible) AS compatible,
   count(*) FILTER(WHERE c.compatible AND c.last_seen>now()-interval '12 seconds') AS online_compatible,
   count(*) FILTER(WHERE c.compatible AND c.bandwidth_ok) AS usable,
   count(*) FILTER(WHERE c.compatible AND c.bandwidth_ok AND c.last_seen>now()-interval '12 seconds') AS online_usable,
   count(*) FILTER(WHERE c.compatible AND c.bandwidth_ok AND c.rate=0) AS free_usable
  FROM (
   SELECT x.last_seen,n.ingress_rate+x.egress_rate AS rate,
    (n.protocol_version>=24 AND x.protocol_version>=24 AND (r.ingress_group_id IS NULL OR x.protocol_version >= $6)
     AND (n.protocol_version>=25 OR n.ingress_rate+x.egress_rate=10000)
     AND (x.tunnel_protocol<>'tls_h3' OR n.protocol_version>=28 AND x.protocol_version>=28)
     AND (x.tunnel_protocol<>'tls_h3' OR x.tls_config->'quic_padding'->>'enabled' IS DISTINCT FROM 'true' OR n.protocol_version>=29 AND x.protocol_version>=29)
     AND (x.tunnel_protocol NOT IN ('random_tcp','random_h2','random_udp','dtls_udp') AND NOT (x.tunnel_protocol='tls_tcp' AND COALESCE(x.tls_config->>'padding_enabled','false')='true' AND COALESCE(x.mux_config->>'enabled','false')='true') OR n.protocol_version>=$5 AND x.protocol_version>=$5)
     AND (x.mux_config->>'enabled' IS DISTINCT FROM 'true' OR x.tunnel_protocol NOT IN ('plain_tcp','tls_tcp','random_tcp','plain_udp','dtls_udp','random_udp') OR n.protocol_version>=34 AND x.protocol_version>=34)
     AND (NOT x.brutal_enabled OR x.tunnel_protocol NOT IN ('tls_h3','plain_udp','dtls_udp','random_udp') OR n.protocol_version>=32 AND x.protocol_version>=32)) AS compatible,
    (NOT x.brutal_enabled OR x.tunnel_protocol NOT IN ('tls_h3','plain_udp','dtls_udp','random_udp') OR n.bandwidth_up_mbps>0 AND n.bandwidth_down_mbps>0 AND x.bandwidth_up_mbps>0 AND x.bandwidth_down_mbps>0) AS bandwidth_ok
   FROM rule_outbound_routes o JOIN nodes x ON x.id=o.egress_node_id WHERE r.egress_group_id IS NOT NULL AND o.rule_id=r.id AND o.ingress_node_id=n.id
  ) c
 ) gc ON true
 WHERE $1 OR r.user_id=$2 ORDER BY r.id DESC
